$AllowedCmds = @('account show', 'extension show', 'extension add', 'graph query', 'provider list', 'role definition list',
                 'security pricing list', 'monitor diagnostic-settings subscription list', 'monitor activity-log list', 'rest', 'account list')

function Write-Step([string]$Msg) { Write-Host ('[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $Msg) }
function Save-Text([string]$Path, [string]$Text) { [IO.File]::WriteAllText($Path, $Text, $Utf8) }
function Save-Json([string]$Name, $Obj) { Save-Text (Join-Path $DataDir ($Name + '.json')) (ConvertTo-Json -InputObject @($Obj) -Depth 8) }
function ConvertTo-SafeKql([string]$s) { if ($s) { return ($s -replace "'", '').Trim() } return '' }
function Test-EmptyList($v) { $s = [string]$v; return ([string]::IsNullOrWhiteSpace($s) -or $s -eq '[]' -or $s -eq 'null') }
function Get-MachineKey($rg, $name) { return (([string]$rg) + '/' + ([string]$name)).ToLower() }
function Add-Log([string]$Step, [int]$Code, [double]$Sec, [string]$Err) {
  $CmdLog.Add([pscustomobject]@{ step = $Step; ok = ($Code -eq 0); seconds = [math]::Round($Sec, 1); error = $Err })
}

# Runs the CLI only for read commands on the allowed list.
function Invoke-AzRaw([string[]]$AzArgs) {
  $path = @(); foreach ($t in $AzArgs) { if ($t.StartsWith('-')) { break }; $path += $t }
  $cmd = $path -join ' '
  if ($AllowedCmds -notcontains $cmd) { throw "Command blocked (not on the read list): az $cmd" }
  if ($cmd -eq 'rest') {
    $j = ' ' + ($AzArgs -join ' ') + ' '
    $okPerm = $j -match ' --url https://management\.azure\.com/subscriptions/[0-9a-fA-F-]{36}/providers/Microsoft\.Authorization/permissions\?api-version=[0-9-]+ '
    $okPric = $j -match ' --url https://management\.azure\.com/subscriptions/[0-9a-fA-F-]{36}/resourceGroups/[^/\s]+/providers/Microsoft\.HybridCompute/machines/[^/\s]+/providers/Microsoft\.Security/pricings/VirtualMachines\?api-version=2024-01-01 '
    $okAgv = $j -match ' --url https://management\.azure\.com/providers/Microsoft\.HybridCompute/osType/(windows|linux)/agentVersions\?api-version=[0-9a-z-]+(&\S*)? '
    $okExm = $j -match ' --url https://management\.azure\.com/subscriptions/[0-9a-fA-F-]{36}/providers/Microsoft\.HybridCompute/locations/[a-z0-9]+/publishers/[^/\s]+/extensionTypes/[^/\s]+/versions\?api-version=[0-9a-z-]+(&\S*)? '
    if ($j -notmatch ' --method get ' -or -not ($okPerm -or $okPric -or $okAgv -or $okExm)) {
      throw 'Command blocked: az rest is allowed only as GET on the effective permissions, per Arc machine Defender plan, and published agent and extension versions APIs.' }
  }
  $prev = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
  try { $out = & az @AzArgs --only-show-errors -o json 2>&1; $code = $LASTEXITCODE }
  finally { $ErrorActionPreference = $prev }
  $err = @($out | Where-Object { $_ -is [System.Management.Automation.ErrorRecord] } | ForEach-Object { $_.ToString() }) -join ' '
  $txt = @($out | Where-Object { $_ -isnot [System.Management.Automation.ErrorRecord] }) -join [Environment]::NewLine
  return [pscustomobject]@{ Code = $code; Text = $txt; Err = $err }
}

# Paginated Azure Resource Graph query; stores the result in $DS[$Name] ($null = failure).
function Invoke-Arg([string]$Name, [string]$Query) {
  Write-Step "Collecting $Name (Resource Graph)"
  $Query = ($Query -replace '\s*\r?\n\s*', ' ').Trim()
  $all = New-Object System.Collections.Generic.List[object]
  $skip = $null; $pages = 0; $ok = $true; $errTxt = ''
  $sw = [Diagnostics.Stopwatch]::StartNew()
  do {
    $a = @('graph', 'query', '-q', $Query, '--first', '1000') + $ArgScope
    if ($skip) { $a += @('--skip-token', $skip) }
    $r = Invoke-AzRaw $a
    if ($r.Code -ne 0) { $ok = $false; $errTxt = $r.Err; break }
    $resp = $r.Text | ConvertFrom-Json
    foreach ($row in @($resp.data)) { if ($null -ne $row) { $all.Add($row) } }
    $skip = $null
    if ($resp.PSObject.Properties['skip_token'] -and $resp.skip_token) { $skip = $resp.skip_token }
    $pages++
  } while ($skip -and $pages -lt 500)
  $sw.Stop()
  $code = 0; if (-not $ok) { $code = 1 }
  Add-Log $Name $code $sw.Elapsed.TotalSeconds $errTxt
  if (-not $ok) { Write-Warning "[$Name] failed: $errTxt"; $DS[$Name] = $null; return }
  $arr = $all.ToArray()
  Save-Json $Name $arr
  $DS[$Name] = $arr
}

# One call per subscription; aggregates the rows with subscriptionId/subscriptionName.
function Invoke-PerSub([string]$Name, [scriptblock]$ArgsFor) {
  Write-Step "Collecting $Name ($($Subs.Count) subscription(s))"
  $all = New-Object System.Collections.Generic.List[object]
  foreach ($s in $Subs) {
    $a = @(& $ArgsFor $s.subscriptionId)
    $sw = [Diagnostics.Stopwatch]::StartNew(); $r = Invoke-AzRaw $a; $sw.Stop()
    Add-Log ($Name + '/' + $s.name) $r.Code $sw.Elapsed.TotalSeconds $r.Err
    if ($r.Code -ne 0) { Write-Warning "[$Name/$($s.name)] failed: $($r.Err)"; continue }
    $obj = $null
    if ($r.Text -and $r.Text.Trim()) { $obj = $r.Text | ConvertFrom-Json }
    if ($null -ne $obj -and $obj -isnot [array] -and $obj.PSObject.Properties['value']) { $obj = $obj.value }
    foreach ($row in @($obj)) {
      if ($null -eq $row) { continue }
      $row | Add-Member -NotePropertyName subscriptionId -NotePropertyValue $s.subscriptionId -Force
      $row | Add-Member -NotePropertyName subscriptionName -NotePropertyValue $s.name -Force
      $all.Add($row)
    }
  }
  $arr = $all.ToArray()
  Save-Json $Name $arr
  $DS[$Name] = $arr
}

# ===================== Context and scope =====================
Write-Step "Azure Arc - security collection $ScriptVersion (read-only)"
$acct = Invoke-AzRaw @('account', 'show')
if ($acct.Code -ne 0) { throw 'Azure CLI not authenticated. Run az login or use Azure Cloud Shell.' }
$Account = $acct.Text | ConvertFrom-Json
if ((Invoke-AzRaw @('extension', 'show', '--name', 'resource-graph')).Code -ne 0) {
  Write-Step 'Installing the Azure CLI resource-graph extension (local, one time)'
  $null = Invoke-AzRaw @('extension', 'add', '--name', 'resource-graph')
}

$SubIds = @()
# Accepts IDs or names as separate items or in one comma- or semicolon-separated string.
$SubIn = @(@($Subscriptions) | ForEach-Object { ([string]$_) -split '[,;]' } | ForEach-Object { $_.Trim().Trim("'", '"') } | Where-Object { $_ })
$SubMiss = @()
foreach ($s in $SubIn) {
  $r = Invoke-AzRaw @('account', 'show', '--subscription', $s)
  if ($r.Code -eq 0) { $SubIds += ($r.Text | ConvertFrom-Json).id } else { $SubMiss += $s }
}
if ($SubMiss.Count) { throw ("Subscription(s) not found or not accessible to the current account: {0}. Check the IDs (each in quotes, or comma-separated) and the active account (az account show). Nothing was collected." -f ($SubMiss -join ', ')) }
$SubIds = @($SubIds | Select-Object -Unique)
if ($ManagementGroup) { $ArgScope = @('--management-groups', $ManagementGroup) }
else {
  $SubIds = @($SubIds | Where-Object { $_ })
  if ($SubIds.Count -eq 0 -and $Account.id) { $SubIds = @([string]$Account.id) }
  if ($SubIds.Count -eq 0) {
    # No default subscription in the CLI: uses the enabled subscriptions of the account.
    $lr = Invoke-AzRaw @('account', 'list', '--query', '[].{id:id,name:name,state:state,tenantId:tenantId}')
    if ($lr.Code -eq 0) { $SubIds = @(@($lr.Text | ConvertFrom-Json) | Where-Object { $_.state -eq 'Enabled' -and (-not $Account.tenantId -or $_.tenantId -eq $Account.tenantId) } | ForEach-Object { [string]$_.id }) }
  }
  if ($SubIds.Count -eq 0) { throw 'No subscription set. Run az account set --subscription <ID> or specify -Subscriptions <ID1>,<ID2>.' }
  $ArgScope = @('--subscriptions') + $SubIds
}
if ($ManagementGroup) { Write-Step ('Scope: management group ' + $ManagementGroup) }
else { Write-Step ('Scope: ' + $SubIds.Count + ' subscription(s): ' + ($SubIds -join ', ')) }
Write-Step ('Parameters: ActivityDays={0}; MaxMachines={3}; RequiredTags={1}; AllowedRegions={2}' -f $ActivityDays, (@($RequiredTags) -join ','), (@($AllowedRegions) -join ','), $MaxMachines)

$Selected = @($Catalog | Where-Object { $Checks -contains $_.id })
$Need = @($Selected | ForEach-Object { $_.ds } | Where-Object { $_ } | Sort-Object -Unique)
function Test-Need([string]$n) { return ($Need -contains $n) }

# One or more resource groups, as separate items or in one comma-separated string.
$RgList = @(@($ResourceGroup) | ForEach-Object { ([string]$_) -split '[,;]' } | ForEach-Object { (ConvertTo-SafeKql $_).ToLower() } | Where-Object { $_ } | Select-Object -Unique)
$rgL = $RgList -join ','; $mL = (ConvertTo-SafeKql $MachineName).ToLower()
$rgIn = ($RgList | ForEach-Object { "'" + $_ + "'" }) -join ','; $rgPath = ($RgList | ForEach-Object { "'/resourcegroups/" + $_ + "/'" }) -join ','
$rgF = ''; $mF = ''; $cF = ''; $ridF = ''
if ($rgL) { $rgF = "| where resourceGroup in~ ($rgIn) "; $ridF += "| where rid has_any ($rgPath) " }
if ($rgL) { Write-Step ('Resource group(s): ' + ($RgList -join ', ')) }
if ($mL) { $mF = "| where name =~ '$mL' "; $cF = "| where tostring(split(id,'/')[8]) =~ '$mL' "; $ridF += "| where rid has '/machines/$mL/' or rid endswith '/machines/$mL' " }

# ===================== Collection (each data item only once) =====================
Invoke-Arg 'subs' "resourcecontainers | where type =~ 'microsoft.resources/subscriptions' | project subscriptionId, name, state = tostring(properties.state)"
if ($null -eq $DS['subs'] -or @($DS['subs']).Count -eq 0) { throw 'No accessible subscription in the specified scope (check IDs and permissions).' }
$Subs = @($DS['subs'])

# ===================== Effective account permissions (read-only) =====================
# Resource Graph does not fail without permission: it returns fewer rows. That is why the account is validated first.
Invoke-PerSub 'permissions' { param($id) @('rest', '--method', 'get', '--url', ('https://management.azure.com/subscriptions/' + $id + '/providers/Microsoft.Authorization/permissions?api-version=2022-04-01')) }
$PermAreas = @(
  @{ area = 'Arc: machines, extensions, and SQL'; ds = @('machines', 'extensions', 'related'); req = $true; actions = @('Microsoft.HybridCompute/machines/read', 'Microsoft.HybridCompute/machines/extensions/read', 'Microsoft.HybridCompute/privateLinkScopes/read', 'Microsoft.AzureArcData/sqlServerInstances/read') },
