function Test-PermAction($Entries, [string]$Action) {
  foreach ($e in @($Entries)) {
    $allow = $false
    foreach ($a in @($e.actions)) { if ($a -and ($Action -like [string]$a)) { $allow = $true; break } }
    if (-not $allow) { continue }
    $deny = $false
    foreach ($n in @($e.notActions)) { if ($n -and ($Action -like [string]$n)) { $deny = $true; break } }
    if (-not $deny) { return $true }
  }
  return $false
}
$PermRows = New-Object System.Collections.Generic.List[object]
foreach ($s in $Subs) {
  $ent = @(@($DS['permissions']) | Where-Object { $_ -and $_.subscriptionId -eq $s.subscriptionId })
  foreach ($pa in $PermAreas) {
    $miss = @(); $st = 'OK'
    if ($ent.Count -eq 0) { $st = 'UNKNOWN' }
    else { $miss = @($pa.actions | Where-Object { -not (Test-PermAction $ent $_) }); if ($miss.Count) { $st = 'FALTA' } }
    $PermRows.Add([pscustomobject]@{ subscription = $s.name; subscriptionId = $s.subscriptionId; area = $pa.area; obrigatoria = $pa.req; status = $st; acoesFaltantes = ($miss -join '; '); datasets = (@($pa.ds) -join ', ') })
  }
}
$PermArr = $PermRows.ToArray()
$PermGapReq = @($PermArr | Where-Object { $_.obrigatoria -and $_.status -ne 'OK' })
$acctType = [string]$Account.user.type
Write-Step ('Account permissions ' + [string]$Account.user.name + ' (' + $acctType + '):')
foreach ($pa in $PermAreas) {
  $rs = @($PermArr | Where-Object { $_.area -eq $pa.area })
  $ok = @($rs | Where-Object { $_.status -eq 'OK' }).Count
  $tag = 'OK  '; if ($ok -lt $rs.Count) { if ($pa.req) { $tag = 'FALTA' } else { $tag = 'INFO' } }
  Write-Host ('  {0,-5} {1} ({2}/{3} subscriptions)' -f $tag, $pa.area, $ok, $rs.Count)
}
if ($PermGapReq.Count) { Write-Warning 'The account does not have full read access in the scope. Collection continues; affected controls will be marked with PARTIAL evidence coverage or ERROR. Recommended: Reader on the management group or on the subscriptions.' }
try { $PermArr | Export-Csv -Path (Join-Path $FindDir 'permissions.csv') -NoTypeInformation -Encoding UTF8 } catch { Write-Verbose $_.Exception.Message }
function Add-PermGap([string[]]$Dsets) {
  if ($script:cur.status -in @('MANUAL', 'ERROR', 'N/A')) { return }
  $areas = @($PermAreas | Where-Object { $_.req -and @(@($_.ds) | Where-Object { $Dsets -contains $_ }).Count })
  if (-not $areas.Count) { return }
  $names = @($areas | ForEach-Object { $_.area })
  $gap = @($PermGapReq | Where-Object { $names -contains $_.area })
  if (-not $gap.Count) { return }
  $subsGap = @($gap | ForEach-Object { $_.subscriptionId } | Sort-Object -Unique)
  $acts = (@($gap | ForEach-Object { $_.acoesFaltantes -split '; ' } | Where-Object { $_ } | Sort-Object -Unique) -join ', ')
  if ($subsGap.Count -ge $Subs.Count) {
    $script:cur.status = 'ERROR'
    $script:cur.detail = 'Insufficient permission in all subscriptions (' + $acts + '); result is not reliable. ' + $script:cur.detail
  } else {
    $script:cur.evidenceCoverage = 'PARTIAL'
    $script:cur.detail = '[PARTIAL: no permission on ' + $subsGap.Count + ' of ' + $Subs.Count + ' subscription(s): ' + $acts + '] ' + $script:cur.detail
  }
}

