# Machine limit (large estates): sample prioritized by risk, then by resource group and name
function Get-MachineRisk($m) {
  $r = 0; $st = [string]$m.status; $os = [string]$m.osSku
  if ($st -eq 'Expired') { $r += 100 } elseif ($st -ne 'Connected') { $r += 80 }
  if ($os -match '2008|2012') { $r += 70 } elseif ($os -match '2016') { $r += 30 }
  $mi = 0; if ([int]::TryParse(((([string]$m.agentVersion) -split '\.') + @('', ''))[1], [ref]$mi) -and $mi -lt 61) { $r += 60 }
  if ([string]$m.mssql -eq 'true') { $r += 20 }
  $tg = ''; if ($m.tags) { $tg = [string]($m.tags | ConvertTo-Json -Compress -Depth 3) }
  if ($tg -match '(?i)"(criticality|criticidade|tier)"\s*:\s*"(high|alta|critical|critica|tier ?0|0)"') { $r += 40 }
  return $r
}
