  foreach ($lb in @('Connected', 'Disconnected up to 6 days', 'Disconnected 7 to 29 days', 'Disconnected 30 to 44 days (expires at 45)', 'Disconnected 45 days or more', 'Expired')) { $bk[$lb] = 0 }
  foreach ($x in @($DS['machines'] | Where-Object { $_ })) {
    $st = [string]$x.status; $dd = 0
    if ($x.lastStatusChange) { try { $dd = [int][math]::Floor(($nowE - [datetime]$x.lastStatusChange).TotalDays) } catch { Write-Verbose $_.Exception.Message } }
    $lb = 'Disconnected 45 days or more'
    if ($st -eq 'Connected') { $lb = 'Connected' } elseif ($st -eq 'Expired') { $lb = 'Expired' } elseif ($dd -lt 7) { $lb = 'Disconnected up to 6 days' } elseif ($dd -lt 30) { $lb = 'Disconnected 7 to 29 days' } elseif ($dd -lt 45) { $lb = 'Disconnected 30 to 44 days (expires at 45)' }
    $bk[$lb]++
    $mi = -1; $null = [int]::TryParse(((([string]$x.agentVersion) -split '\.') + @('', ''))[1], [ref]$mi)
    $ak = $(if ($mi -ge 0) { '1.' + $mi } else { '?' }); if (-not $agv.ContainsKey($ak)) { $agv[$ak] = @(0, $mi) }; $agv[$ak][0]++
  }
  $EstRows = New-Object System.Collections.Generic.List[object]
