$AgentLatestLive = 0; $ExtLatest = @{}; $RefRows = New-Object System.Collections.Generic.List[object]
function Get-RestItem([string]$Url) {
  $items = New-Object System.Collections.Generic.List[object]; $n = 0
  while ($Url -and $n -lt 20) {
    $n++; $r = Invoke-AzRaw @('rest', '--method', 'get', '--url', $Url)
    if ($r.Code -ne 0 -or -not $r.Text) { Add-Log 'refVersions' $r.Code 0 $r.Err; break }
    $o = $r.Text | ConvertFrom-Json; foreach ($v in @($o.value)) { $items.Add($v) }; $Url = [string]$o.nextLink
  }
  return $items.ToArray()
}
if ((Test-Need 'machines') -or (Test-Need 'extensions')) {
  Write-Step 'Querying published agent and extension versions'
  foreach ($os in @('windows', 'linux')) {
    foreach ($v in @(Get-RestItem ('https://management.azure.com/providers/Microsoft.HybridCompute/osType/' + $os + '/agentVersions?api-version=2025-01-13'))) {
      $mi = 0; if ([int]::TryParse(((([string]$v.agentVersion) -split '\.') + @('', ''))[1], [ref]$mi) -and $mi -gt $AgentLatestLive) { $AgentLatestLive = $mi }
    }
  }
  $RefRows.Add([pscustomobject]@{ item = 'Connected Machine agent'; location = 'global'; latest = $(if ($AgentLatestLive) { '1.' + $AgentLatestLive } else { '' }) })
  $locOf = @{}; foreach ($mm in @($DS['machines'])) { $locOf[(Get-MachineKey $mm.resourceGroup $mm.name)] = ([string]$mm.location).ToLower() }
  $combos = @{}; foreach ($e in @($DS['extensions'])) { $lo = $locOf[(Get-MachineKey $e.resourceGroup $e.machine)]; if ($lo -and $e.publisher -and $e.extType) { $combos[($lo + '|' + $e.publisher + '|' + $e.extType).ToLower()] = @($lo, $e.publisher, $e.extType) } }
  $sid = @($Subs)[0].subscriptionId; $k = 0
  foreach ($c in $combos.Keys) {
    $k++; if ($k -gt 40) { break }
    $p = $combos[$c]; $best = $null
    foreach ($v in @(Get-RestItem ('https://management.azure.com/subscriptions/' + $sid + '/providers/Microsoft.HybridCompute/locations/' + $p[0] + '/publishers/' + $p[1] + '/extensionTypes/' + $p[2] + '/versions?api-version=2025-01-13'))) {
      $vv = $null; if ([version]::TryParse([string]$v.properties.version, [ref]$vv) -and (-not $best -or $vv -gt $best)) { $best = $vv }
    }
    if ($best) { $ExtLatest[$c] = $best; $RefRows.Add([pscustomobject]@{ item = $p[1] + '/' + $p[2]; location = $p[0]; latest = [string]$best }) }
  }
  Save-Json 'refVersions' $RefRows.ToArray(); $DS['refVersions'] = $RefRows.ToArray()
}
