  $all = New-Object System.Collections.Generic.List[object]; $ok = 0; $i = 0
  foreach ($x in $ms) {
    $i++; if ($i % 25 -eq 0) { Write-Step ("  pricingRes: {0} of {1}" -f $i, $ms.Count) }
    $u = 'https://management.azure.com/subscriptions/' + $x.subscriptionId + '/resourceGroups/' + $x.resourceGroup + '/providers/Microsoft.HybridCompute/machines/' + $x.name + '/providers/Microsoft.Security/pricings/VirtualMachines?api-version=2024-01-01'
    $sw = [Diagnostics.Stopwatch]::StartNew(); $r = Invoke-AzRaw @('rest', '--method', 'get', '--url', $u); $sw.Stop()
    Add-Log ('pricingRes/' + $x.name) $r.Code $sw.Elapsed.TotalSeconds $r.Err
    $row = [ordered]@{ subscriptionId = $x.subscriptionId; resourceGroup = $x.resourceGroup; machine = $x.name; tier = ''; subPlan = ''; inherited = ''; inheritedFrom = ''; extensions = ''; error = '' }
    if ($r.Code -eq 0 -and $r.Text) {
      $ok++; $p = ($r.Text | ConvertFrom-Json).properties
      $row.tier = [string]$p.pricingTier; $row.subPlan = [string]$p.subPlan; $row.inherited = [string]$p.inherited; $row.inheritedFrom = [string]$p.inheritedFrom
      $row.extensions = (@($p.extensions | Where-Object { [string]$_.isEnabled -eq 'True' } | ForEach-Object { $_.name }) -join ', ')
    } else { $row.error = ([string]$r.Err).Substring(0, [math]::Min(200, ([string]$r.Err).Length)) }
    $all.Add([pscustomobject]$row)
  }
  $arr = $all.ToArray(); Save-Json 'pricingRes' $arr
  if ($ms.Count -and -not $ok) { $DS['pricingRes'] = $null } else { $DS['pricingRes'] = $arr }
}
