# ===================== Avaliacao =====================
function Write-Result([string]$Status, [int]$Found, [string]$Detail, $Rows = $null, [string]$Coverage = 'FULL') {
  $script:cur.status = $Status; $script:cur.found = $Found; $script:cur.detail = $Detail; $script:cur.evidenceCoverage = $Coverage
  # Control Result and Evidence Coverage are independent axes. A measured condition can
  # conclusively FAIL while coverage remains PARTIAL (for example an external SOC or
  # contractual entitlement is outside the collected scope). PARTIAL as a result is used
  # only when the evidence cannot support PASS/WARN/FAIL for the criterion itself.
  if ($Status -eq 'PARTIAL') { $script:cur.evidenceCoverage = 'PARTIAL' }
  elseif ($Status -eq 'ERROR') { $script:cur.evidenceCoverage = 'ERROR' }
  elseif ($Status -in @('N/A', 'TODO', 'MANUAL')) { $script:cur.evidenceCoverage = 'NONE' }
  $arr = @($Rows | Where-Object { $null -ne $_ })
  if ($arr.Count -gt 0) {
    $arr | Export-Csv -Path (Join-Path $FindDir ($script:cur.id + '.csv')) -NoTypeInformation -Encoding UTF8
    $script:cur.file = 'findings/' + $script:cur.id + '.csv'
  }
}
function Get-ArcMachine { return @($DS['machines']) }
function Get-ArcConnected { return @($DS['machines'] | Where-Object { $_.status -eq 'Connected' }) }
# Arc scope: everything is evaluated from the collected Microsoft.HybridCompute/machines
function Get-ArcScope {
  if ($script:ArcScopeCache) { return $script:ArcScopeCache }
  $s = @{ subs = @{}; rgs = @{} }
  foreach ($m in @($DS['machines'])) {
    $sub = ([string]$m.subscriptionId).ToLower(); $rg = ([string]$m.resourceGroup).ToLower()
    if ($sub) { $s.subs[$sub] = $true; $s.rgs[$sub + '/' + $rg] = $true }
  }
  $script:ArcScopeCache = $s; return $s
}
function Test-ArcScope([string]$Scope) {
  $sc = ([string]$Scope).ToLower().TrimEnd('/')
  if (-not $sc) { return $true }
  if ($sc -like '/providers/microsoft.management/managementgroups/*') { return $true }
  $a = Get-ArcScope
  if ($sc -match '^/subscriptions/([^/]+)$') { return $a.subs.ContainsKey($Matches[1]) }
  if ($sc -match '^/subscriptions/([^/]+)/resourcegroups/([^/]+)') { return $a.rgs.ContainsKey($Matches[1] + '/' + $Matches[2]) }
  return $false
}
function Test-ArcRg([string]$Sub, [string]$Rg) { return (Get-ArcScope).rgs.ContainsKey(([string]$Sub).ToLower() + '/' + ([string]$Rg).ToLower()) }
function Get-ArcWorkspaceId {
  $info = Get-DcrInfo; $ids = @{}
  foreach ($x in @($DS['dcra'])) { $d = ([string]$x.dcrId).ToLower(); if ($info.ContainsKey($d)) { foreach ($w in @($info[$d].workspaces)) { $ids[$w] = $true } } }
  return $ids
}
function Get-ExtIndex([string]$Pattern) {
  $h = @{}; foreach ($e in @($DS['extensions'])) { if ($e.extType -match $Pattern) { $h[(Get-MachineKey $e.resourceGroup $e.machine)] = $e.state } }; return $h
}

