function Get-DcrInfo {
  $out = @{}
  foreach ($d in @($DS['related'] | Where-Object { $_.type -eq 'microsoft.insights/datacollectionrules' })) {
    $ws = @(); $st = @()
    try { if ($d.dcrDest) { $ws = @(@($d.dcrDest | ConvertFrom-Json) | ForEach-Object { ([string]$_.workspaceResourceId).ToLower() } | Where-Object { $_ }) } } catch { Write-Verbose $_.Exception.Message }
    try { if ($d.dcrFlows) { $st = @(@($d.dcrFlows | ConvertFrom-Json) | ForEach-Object { @($_.streams) } | Where-Object { $_ } | Sort-Object -Unique) } } catch { Write-Verbose $_.Exception.Message }
    $out[([string]$d.id).ToLower()] = [pscustomobject]@{ name = $d.name; resourceGroup = $d.resourceGroup; workspaces = $ws; streams = $st }
  }
  return $out
}
