  $licTxt = (@($lic | ForEach-Object { [string]$_.name + ' (' + $_.licBilling + ', ' + $_.licSize + ' cores, ' + $_.licState + ')' }) -join '; ')
  if (-not $licTxt) { $licTxt = '0' }
  $ltTxt = (@($lt.Keys | Sort-Object | ForEach-Object { $_ + ': ' + $lt[$_] }) -join '; ')
  $det = ("{0} SQL Server extension(s). LicenseType: {1}. Using a physical core license (pCore): {2}; pCore licenses in scope: {3}. Usage upload with error: {4}; no upload for more than 24 hours: {5}; failed extension: {6}; machine not Connected: {7}; empty LicenseType: {8}; OS older than Windows Server 2016: {9}. The hourly usage upload supports PAYG billing and the usage reporting of Software Assurance licenses." -f $sx.Count, $ltTxt, $pc, $licTxt, $nUp, $nOld, $nFail, $nOff, $nLt, $nOs)
  $det += (" pCore license with LicenseType different from the billingPlan or no license in scope: {0} (the documentation requires LicenseType to match the license billingPlan)." -f $nMis)
  $arr = $rows.ToArray()
  if ($nUp -or $nOld -or $nFail -or $nOff) { Write-Result 'FAIL' $arr.Count ($det + ' The observed technical failure is conclusive; Evidence Coverage is PARTIAL only for contractual entitlement/licensing evidence outside the package.') $arr 'PARTIAL' }
  elseif ($arr.Count) { Write-Result 'WARN' $arr.Count $det $arr }
  else { Write-Result 'PASS' 0 $det }
}
$Eval['CHK-51'] = {
  $now = Get-Date
  $win = @(Get-ArcMachine | Where-Object { ([string]$_.osSku) -match 'Windows' })
  $rows = New-Object System.Collections.Generic.List[object]
  $nEol = 0; $n16 = 0; $n16gap = 0
  foreach ($x in $win) {
    $sku = [string]$x.osSku; $esuOk = ([string]$x.esu -eq 'Assigned')
    $minor = -1; $parts = ([string]$x.agentVersion) -split '\.'; if ($parts.Count -ge 2) { $minor = [int]($parts[1] -replace '\D', '0') }
    $sit = $null
    if ($sku -match '2008') { $sit = 'Not supported: Windows Server 2008 outside the ESU via Arc cycle'; $nEol++ }
    elseif ($sku -match '2012') {
      if ($now -ge [datetime]'2026-10-14') { $sit = 'No updates: Windows Server 2012/2012 R2 ESU ended on 2026-10-13 (licenses deactivated on 2026-10-14)'; $nEol++ }
      elseif (-not $esuOk) { $sit = 'Windows Server 2012 without ESU assigned'; $nEol++ }
    }
    elseif ($sku -match '2016') {
      $n16++
      if (-not $esuOk) { $sit = 'End of support on 2027-01-12: assign ESU via Arc (configurable since 2026-08-03; billing starts 2027-01-13)'; $n16gap++ }
      elseif ($minor -ge 0 -and $minor -lt 62) { $sit = 'ESU assigned, but the agent must be 1.62 or later'; $n16gap++ }
      else { $sit = 'Windows Server 2016 ESU assigned' }
    }
    if ($sit) { $rows.Add([pscustomobject]@{ name = $x.name; resourceGroup = $x.resourceGroup; subscriptionId = $x.subscriptionId; osSku = $sku; agentVersion = $x.agentVersion; esu = $x.esu; situacao = $sit }) }
  }
  $arr = $rows.ToArray()
  if ($nEol) { Write-Result 'FAIL' $arr.Count ("{0} 2008/2012/2012 R2 server(s) without security updates; {1} Windows Server 2016 ({2} without ESU ready for 2027-01-12)." -f $nEol, $n16, $n16gap) $arr }
  elseif ($n16gap) { Write-Result 'WARN' $arr.Count ("{0} Windows Server 2016 without ESU ready for end of support on 2027-01-12." -f $n16gap) $arr }
  elseif ($n16) { Write-Result 'INFO' $arr.Count ("{0} Windows Server 2016 with ESU assigned (billing starts 2027-01-13)." -f $n16) $arr }
  else { Write-Result 'PASS' 0 'No Windows Server 2008/2012/2016 in scope.' }
}
$Eval['CHK-54'] = {
  $al = @($DS['alerts']); $vu = @($DS['vulns']); $ss = @($DS['secscore'])
  $hiAl = @($al | Where-Object { $_.severidade -eq 'High' })
  $vHi = @($vu | Where-Object { @('High', 'Critical') -contains [string]$_.severidade })
  $mAl = @($al | ForEach-Object { $_.machine } | Where-Object { $_ } | Sort-Object -Unique).Count
  $scTxt = (@($ss | Where-Object { $_.maximo } | ForEach-Object { $nm = $_.subscriptionId; $sx = @($Subs | Where-Object { $_.subscriptionId -eq $nm }) | Select-Object -First 1; if ($sx) { $nm = $sx.name }; $nm + ': ' + [math]::Round(100 * [double]$_.atual / [double]$_.maximo, 1) + '%' }) -join '; ')
  if (-not $scTxt) { $scTxt = 'not available' }
  $top = ''; if ($vu.Count) { $t = $vu | Sort-Object { [int]$_.maquinas } -Descending | Select-Object -First 1; $top = " Widest reach: $($t.vulnerabilidade) ($($t.maquinas) machine(s))." }
  $rows = New-Object System.Collections.Generic.List[object]
  foreach ($x in $al) { $rows.Add([pscustomobject]@{ tipo = 'Active alert'; item = $x.alerta; severidade = $x.severidade; maquinas = 1; machine = $x.machine; status = $x.status; inicio = $x.inicio }) }
  foreach ($x in @($vu | Select-Object -First 200)) { $rows.Add([pscustomobject]@{ tipo = 'Vulnerabilidade'; item = $x.vulnerabilidade; severidade = $x.severidade; maquinas = $x.maquinas; machine = ''; status = 'Unhealthy'; inicio = '' }) }
  $arr = $rows.ToArray()
  $det = "Active security alerts: {0} (High: {1}) on {2} machine(s). Distinct vulnerabilities: {3} (High/Critical: {4}).{5} Subscription Secure Score (includes non-Arc resources): {6}. Vulnerability coverage depends on the Defender plan and MDE." -f $al.Count, $hiAl.Count, $mAl, $vu.Count, $vHi.Count, $top, $scTxt
  $m = @(Get-ArcConnected); $mde = Get-ExtIndex '^MDE\.(Windows|Linux)$'; $covered = @($m | Where-Object { $mde.ContainsKey((Get-MachineKey $_.resourceGroup $_.name)) }).Count
  $det += (" MDE extension deployed through Arc on {0} of {1} connected machines." -f $covered, $m.Count)
  if ($hiAl.Count) { Write-Result 'FAIL' $arr.Count $det $arr $(if ($covered -lt $m.Count) { 'PARTIAL' } else { 'FULL' }) }
  elseif ($al.Count -or $vHi.Count) { Write-Result 'WARN' $arr.Count $det $arr $(if ($covered -lt $m.Count) { 'PARTIAL' } else { 'FULL' }) }
  elseif (-not $m.Count -or $covered -lt $m.Count) { Write-Result 'PARTIAL' 0 ($det + ' Zero findings without confirmed coverage is not evidence of no exposure.') }
  else { Write-Result 'PASS' 0 $det }
}
$Eval['CHK-53'] = {
  # List prices in USD (Azure Arc pricing page, checked on 2026-10-22). Estimate, not an invoice.
  $P_DEF1 = 5; $P_DEF2 = 15; $P_AUM = 5; $P_GC = 6; $P_WSPAYG = 33.58
  $m = @(Get-ArcConnected)
  if (-not $m.Count) { Write-Result 'N/A' 0 'No connected machines in scope.'; return }
  $pr = @($DS['pricing']); $gc = @($DS['gcAssign'])
  $ct = Get-ExtIndex '^ChangeTracking-(Windows|Linux)$'; $ama = Get-ExtIndex '^AzureMonitor(Windows|Linux)Agent$'
  $gcIx = @{}; foreach ($g in $gc) { $gcIx[(Get-MachineKey $g.resourceGroup $g.machine)] = [int]$g.assignments }
  $rows = New-Object System.Collections.Generic.List[object]
  $tot = 0.0; $save = 0.0; $nSave = 0; $nBen = 0; $nAma = 0
  foreach ($x in $m) {
    $k = Get-MachineKey $x.resourceGroup $x.name
    $vm = @($pr | Where-Object { $_.subscriptionId -eq $x.subscriptionId -and $_.name -eq 'VirtualMachines' }) | Select-Object -First 1
    $def = 'Free'; if ($vm -and $vm.pricingTier -eq 'Standard') { $def = 'P1'; if ([string]$vm.subPlan -match 'P2') { $def = 'P2' } }
    $vr = @($DS['pricingRes'] | Where-Object { $_ -and -not $_.error -and (Get-MachineKey $_.resourceGroup $_.machine) -eq $k }) | Select-Object -First 1
    if ($vr) { $def = 'Free'; if ($vr.tier -eq 'Standard') { $def = 'P1'; if ([string]$vr.subPlan -match 'P2') { $def = 'P2' } } }
    $isWin = ([string]$x.osType -eq 'windows')
    $sa = $isWin -and (([string]$x.saCustomer -eq 'true') -or ([string]$x.wsMgmt -match 'WindowsServerAzureArcMgmt' -and [string]$x.wsMgmt -match 'Enabled'))
    $payg = $isWin -and ([string]$x.wsPayg -eq 'Enabled')
    $esu = ([string]$x.esu -eq 'Assigned')
    $ben = @(); if ($def -eq 'P2') { $ben += 'Defender P2' }; if ($sa) { $ben += 'Attested SA' }; if ($payg) { $ben += 'WS PAYG' }; if ($esu) { $ben += 'ESU' }
    $covered = ($ben.Count -gt 0)
    $aum = (([string]$x.patchAssessment -eq 'AutomaticByPlatform') -or ([string]$x.linuxPatchAssessment -eq 'AutomaticByPlatform'))
    $gcn = 0; if ($gcIx.ContainsKey($k)) { $gcn = $gcIx[$k] }
    $hasCt = $ct.ContainsKey($k)
    $cDef = 0; if ($def -eq 'P1') { $cDef = $P_DEF1 } elseif ($def -eq 'P2') { $cDef = $P_DEF2 }
    $cAum = 0; if ($aum -and -not $covered) { $cAum = $P_AUM }
    $cGc = 0; if (($gcn -gt 0 -or $hasCt) -and -not $covered) { $cGc = $P_GC }
    $cPay = 0; if ($payg -and $x.cores) { $cPay = [math]::Round(([double]$x.cores) * $P_WSPAYG, 2) }
    $sub = $cDef + $cAum + $cGc + $cPay
    $tot += $sub
    if ($covered) { $nBen++ }
    $hasAma = $ama.ContainsKey($k); if ($hasAma) { $nAma++ }
    $opp = 0; if ($isWin -and -not $covered -and ($cAum + $cGc) -gt 0) { $opp = $cAum + $cGc; $save += $opp; $nSave++ }
    $var = @(); if ($hasAma) { $var += 'Log Analytics (US$ 2,76/GB)' }
    $rows.Add([pscustomobject]@{ name = $x.name; resourceGroup = $x.resourceGroup; subscriptionId = $x.subscriptionId; os = $x.osType; defender = $def; beneficios = ($ben -join ', '); updateManager = $cAum; machineConfigChangeTracking = $cGc; defenderUsd = $cDef; wsPaygUsd = $cPay; cores = $x.cores; estimativaUsdMes = $sub; economiaSeSaAtestado = $opp; variaveis = ($var -join ', '); atribuicoesGc = $gcn })
  }
  $arr = $rows.ToArray()
  $msg = "List price estimate: US$ {0:N2}/month for {1} connected server(s) (Defender, Update Manager, Machine Configuration/Change Tracking, and WS PAYG). {2} with benefit (Defender P2, attested SA, WS PAYG, or ESU). {3} with AMA: Log Analytics cost per GB not estimated." -f $tot, $m.Count, $nBen, $nAma
  if ($nSave) { Write-Result 'WARN' $arr.Count ($msg + (" {0} Windows Server paying for Update Manager/Machine Configuration without benefit: up to US$ {1:N2}/month avoidable if they have Software Assurance (attest in Azure Arc > Azure Benefits - Windows Server)." -f $nSave, $save)) $arr }
  else { Write-Result 'INFO' $arr.Count $msg $arr }
}
