  $script:cur = [ordered]@{ id = $c.id; domain = $c.domain; title = $c.title; severity = $c.sev; type = $c.type; status = 'MANUAL'; evidenceCoverage = 'NONE'; found = 0; detail = ''; file = ''; evidenceSources = (@($c.ds) | ForEach-Object { 'data/' + $_ + '.json' }) -join '; '; evidenceQuery = 'Collector dataset(s); CLI calls and failures are recorded in results.json and run.log'; collectedAt = $Start.ToUniversalTime().ToString('o'); evidenceScope = ''; evidenceDenominator = 'Defined by the check detail and findings rows'; evidenceExclusions = 'Machine sampling when MaxMachines is set; external authorities require documentary evidence'; evidenceFreshness = 'Point-in-time at collection; Activity Log uses ActivityDays'; evidenceFailureBehavior = 'Missing dataset = ERROR; proxy/external scope = PARTIAL; not applicable = N/A' }
  if ($c.type -eq 'manual') { $cur.status = 'MANUAL'; $cur.evidenceCoverage = 'NONE'; $cur.detail = 'Documentary control: validate with the customer and record the evidence.' }
  else {
    $missing = @(@($c.ds) | Where-Object { $_ -and ($null -eq $DS[$_]) })
