$L.Add('')
$L.Add('## Priorities and evidence gaps (FAIL, WARN, PARTIAL, ERROR)')
$L.Add('')
$L.Add('| Status | Sev. | ID | Check | Findings | Detail |')
$L.Add('|---|---|---|---|---:|---|')
$prio = @(foreach ($x in $Results) {
    if (@('FAIL', 'WARN', 'PARTIAL', 'ERROR') -notcontains [string]$x.status) { continue }
    $k1 = 3; if ([string]$x.status -eq 'FAIL') { $k1 = 0 } elseif ([string]$x.status -eq 'ERROR') { $k1 = 1 } elseif ([string]$x.status -eq 'PARTIAL') { $k1 = 2 }
    $k2 = 1; $sv = [string]$x.severity; if ($sv -eq 'High') { $k2 = 0 } elseif ($sv -eq 'Low') { $k2 = 2 }
    [pscustomobject]@{ k1 = [int]$k1; k2 = [int]$k2; id = [string]$x.id; item = $x } }) | Sort-Object k1, k2, id | ForEach-Object { $_.item }
foreach ($x in $prio) { $L.Add("| $($x.status) | $($x.severity) | $($x.id) | $(ConvertTo-MdCell $x.title) | $($x.found) | $(ConvertTo-MdCell $x.detail) |") }
if (-not @($prio).Count) { $L.Add('| - | - | - | No FAIL/WARN/PARTIAL/ERROR | 0 | - |') }
