  foreach ($x in $d.Group) { $L.Add("| $($x.id) | $(ConvertTo-MdCell $x.title) | $($x.severity) | $($x.status) | $($x.evidenceCoverage) | $($x.found) | $(ConvertTo-MdCell $x.detail) | $($x.file) |") }
}
