foreach ($x in $PermArr) { $L.Add('| ' + (ConvertTo-MdCell $x.subscription) + ' | ' + $x.area + ' | ' + $x.obrigatoria + ' | ' + $x.status + ' | ' + (ConvertTo-MdCell $x.acoesFaltantes) + ' |') }
