function Add-Prop($Obj, [string]$Name, [scriptblock]$Value) {
  $v = $null
  try { $v = & $Value } catch { Write-Warning ('Field ' + $Name + ' ignored (row ' + $_.InvocationInfo.ScriptLineNumber + '): ' + $_.Exception.Message) }
  $Obj | Add-Member -NotePropertyName $Name -NotePropertyValue $v -Force
}
